/* @lc app=leetcode id=3509 lang=kotlin */ class Solution { fun maxProduct(nums: IntArray, k: Int, limit: Int): Int = nums.fold(HashSet<Long>()) { st, x -> HashSet(st).also { nw -> st.forEach { e -> (e % 2).toInt().let { p -> (e / 2).let { rest -> (rest % 5003).toInt().let { pr -> (rest / 5003 - 2000).toInt().let { sm -> nw.add((((sm + (if (p == 0) x else -x) + 2000).toLong() * 5003 + minOf(pr.toLong() * x, limit + 1L)) * 2) + (1 - p)) } } } } }.let { nw.add(((x + 2000).toLong() * 5003 + minOf(x, limit + 1)) * 2 + 1) } } }.filter { e -> (e / 2 / 5003 - 2000).toInt() == k && (e / 2) % 5003 <= limit }.maxOfOrNull { ((it / 2) % 5003).toInt() } ?: -1 }